import { labelPercent, NA, toPercent } from '../reports';

describe('reports', () => {
  describe('labelPercent', () => {
    it('should return value as a percentage', () => {
      expect(labelPercent(0.42)).toEqual('42%');
    });

    test('should handle "N/A" string', () => {
      expect(labelPercent(NA)).toEqual(NA);
    });
  });

  describe('toPercent', () => {
    it('should return value as a integer percentage', () => {
      expect(toPercent(0.574)).toEqual('57%');
    });

    it('should return value as a decimal percentage', () => {
      expect(toPercent(0.1983, 2)).toEqual('19.83%');
    });
  });
});
